#include <vector>

int countPrimes(int n) {
    if (n <= 2) return 0;
    std::vector<bool> isPrime(n, true);
    isPrime[0] = isPrime[1] = false;
    for (int p = 2; p * p < n; ++p) {
        if (isPrime[p]) {
            for (int mult = p * p; mult < n; mult += p) {
                isPrime[mult] = false;
            }
        }
    }
    int count = 0;
    for (bool p : isPrime) if (p) count++;
    return count;
}

